for fp, imps in file_imports.items():
    for target in imps:
        if target.startswith('heretek_swarm'):
            hsw_targets.add(target)

print(f"Internal heretek_swarm targets: {len(hsw_targets)}")
print("HERE_SWARM_TARGETS:", sorted(hsw_targets))

# Count by top-level target
target_counts = {}
for fp, imps in file_imports.items():
    for target in imps:
        # Normalize: for heretek_swarm.x, count as heretek_swarm
        if target.startswith('heretek_swarm'):
            top = 'heretek_swarm'
        elif target.startswith('<relative'):
            top = '<relative>'
        else:
            top = target
        target_counts[top] = target_counts.get(top, 0) + 1

print("\nTop-level import target frequency (top 40):")
for t, c in sorted(target_counts.items(), key=lambda x: -x[1])[:40]:
    print(f"  {t}: {c}")

# Find files importing from src/
src_importers = []
for fp, imps in file_imports.items():
    for target in imps:
        if 'src' in target or 'cli' in target:
            src_importers.append((fp, target))
print(f"\nFiles importing from src/cli: {len(src_importers)}")
for f, t in src_importers[:20]:
    print(f"  {f} -> {t}")

